"""
Discover and set flight modes at runtime.

 The modes are queried from the vehicle using the MAVLink standard modes
 protocol (AVAILABLE_MODES, CURRENT_MODE). For autopilots that don't
 implement it, a list of known modes is used as a fallback.

 Modes are identified by name. Standard modes have a fixed name, e.g.
 "Position" or "Mission", custom modes use the name reported by the vehicle.
"""

import asyncio
from typing import AsyncGenerator
from mavsdk.plugins.modes import (
    Modes,
    ModesResult,
    ModesError,
    StandardMode,
    Mode,
)


class ModesAsync:
    """
       Discover and set flight modes at runtime.

    The modes are queried from the vehicle using the MAVLink standard modes
    protocol (AVAILABLE_MODES, CURRENT_MODE). For autopilots that don't
    implement it, a list of known modes is used as a fallback.

    Modes are identified by name. Standard modes have a fixed name, e.g.
    "Position" or "Mission", custom modes use the name reported by the vehicle.

       Async wrapper around :class:`Modes` that mirrors the gRPC-based
       asyncio API while using the ctypes-based C library directly.
    """

    def __init__(self, system):
        self._plugin = Modes(system._system)

    async def subscribe_available_modes(self) -> AsyncGenerator[Mode, None]:
        """
               Subscribe to the list of available modes.

        The list is updated whenever the vehicle reports that its modes have changed.

               Yields
               ------
               mode : Mode
                    The next update
        """
        loop = asyncio.get_running_loop()
        queue: asyncio.Queue = asyncio.Queue()

        def callback(data, _user_data):
            loop.call_soon_threadsafe(queue.put_nowait, data)

        handle = self._plugin.subscribe_available_modes(callback)
        try:
            while True:
                yield await queue.get()
        finally:
            self._plugin.unsubscribe_available_modes(handle)

    async def available_modes(self):
        """
               Subscribe to the list of available modes.

        The list is updated whenever the vehicle reports that its modes have changed.

               Returns
               -------
               modes : Mode
               Raises
               ------
               ModesError
                   If the request fails. The error contains the reason for the failure.
        """
        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(None, lambda: self._plugin.available_modes())

    async def subscribe_current_mode(self) -> AsyncGenerator[Mode, None]:
        """
        Subscribe to the current mode.

        Yields
        ------
        mode : Mode
             The next update
        """
        loop = asyncio.get_running_loop()
        queue: asyncio.Queue = asyncio.Queue()

        def callback(data, _user_data):
            loop.call_soon_threadsafe(queue.put_nowait, data)

        handle = self._plugin.subscribe_current_mode(callback)
        try:
            while True:
                yield await queue.get()
        finally:
            self._plugin.unsubscribe_current_mode(handle)

    async def current_mode(self):
        """
        Subscribe to the current mode.

        Returns
        -------
        mode : Mode
        Raises
        ------
        ModesError
            If the request fails. The error contains the reason for the failure.
        """
        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(None, lambda: self._plugin.current_mode())

    async def set_mode(self, name):
        """
               Set mode by name.

        The name needs to match exactly (case-sensitive) the name of one of the available modes.

               Parameters
               ----------
               name : str
               Raises
               ------
               ModesError
                   If the request fails. The error contains the reason for the failure.
        """
        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(None, lambda: self._plugin.set_mode(name))

    async def set_standard_mode(self, standard_mode):
        """
        Set a standard mode.

        Parameters
        ----------
        standard_mode : StandardMode
        Raises
        ------
        ModesError
            If the request fails. The error contains the reason for the failure.
        """
        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(
            None, lambda: self._plugin.set_standard_mode(standard_mode)
        )

    def destroy(self):
        self._plugin.destroy()

    def __del__(self):
        self.destroy()
